    h = observation.get("grid_height", 0)

    def pt(v):
        if isinstance(v, dict):
            for a, b in (("x", "y"), ("col", "row"), ("j", "i")):
                if a in v and b in v and isinstance(v[a], (int, float)) and isinstance(v[b], (int, float)):
                    return [int(v[a]), int(v[b])]
        if isinstance(v, (list, tuple)) and len(v) >= 2 and isinstance(v[0], (int, float)) and isinstance(v[1], (int, float)):
            return [int(v[0]), int(v[1])]
        return None

    def scan(x):
        p = pt(x)
        if p is not None:
            return p
        if isinstance(x, dict):
            for v in x.values():
                p = scan(v)
                if p is not None:
                    return p
        if isinstance(x, (list, tuple)):
            for v in x:
                p = scan(v)
                if p is not None:
                    return p
        return None

    me = scan(observation.get("self_position"))
    if me is None:
        me = scan(observation.get("self_path"))
    op = scan(observation.get("opponent_position"))
    if me is None:
        return [0, 0]

    res = []
    for r in observation.get("resources", []):
        p = scan(r)
        if p is not None:
            res.append(p)
    obs = {tuple(scan(o)) for o in observation.get("obstacles", []) if scan(o) is not None}
    bad = set(obs)
    if op is not None:
        bad.add((op[0], op[1]))

    tx, ty = None, None
    if res:
        best = 10**9
        for x, y in res:
            d = abs(x - me[0]) + abs(y - me[1])
            if d < best:
                best, tx, ty = d, x, y
    elif op is not None:
        tx, ty = op[0], op[1]

    moves = [(1, 0), (-1, 0), (0, 1), (0, -1), (0, 0)]
    best = None
    bestv = None
    for dx, dy in moves:
        nx, ny = me[0] + dx, me[1] + dy
        if w and (nx < 0 or nx >= w or nx >= w):
            continue
        if h and (ny < 0 or ny >= h or ny >= h):
            continue
        if (nx, ny) in bad and (tx is None or (nx, ny) != (tx, ty)):
            continue
        v = 0
        if tx is not None:
            v -= abs(tx - nx) + abs(ty - ny) * 2
        if op is not None:
            v += abs(op[0] - nx) + abs(op[1] - ny)
        if dx == 0 and dy == 0:
            v -= 1
        if bestv is None or v > bestv:
            bestv, best = v, [dx, dy]
    return best if best is not None else [0, 0]

